compare.check:
(args, got, expected) => {
      const ops = args.ops, a = args.args;
      if (!Array.isArray(got) || got.length !== ops.length) return false;
      const c = new Map();
      for (let i = 0; i < ops.length; i++) {
        const op = ops[i];
        if (op === "getMaxKey" || op === "getMinKey") {
          if (c.size === 0) { if (got[i] !== "") return false; continue; }
          let best = op === "getMaxKey" ? -Infinity : Infinity;
          for (const v of c.values()) best = op === "getMaxKey" ? Math.max(best, v) : Math.min(best, v);
          if (c.get(got[i]) !== best) return false;
          continue;
        }
        if (i > 0 && got[i] !== null) return false;
        if (op === "inc") c.set(a[i][0], (c.get(a[i][0]) || 0) + 1);
        else if (op === "dec") { const v = c.get(a[i][0]) - 1; if (v === 0) c.delete(a[i][0]); else c.set(a[i][0], v); }
      }
      return got[0] === null;
    }
